#!/usr/bin/env python3
"""Smoke checks for ES/EN partner pages generated by fuente/build.py."""
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
errors = []
for rel, text in (
    ("partners/index.html", "Una calculadora útil para tus viajeros"),
    ("en/partners/index.html", "A useful calculator for your travellers"),
):
    f = ROOT / "docs" / rel
    if not f.is_file():
        errors.append(f"Missing partner page: {rel}")
        continue
    html = f.read_text(encoding="utf-8")
    for needle in (text, 'src="/widget/"', "mailto:vuelosclaim@gmail.com",
                   "9,90", "19,90", "readonly", "https://vuelosclaim.eu/widget/"):
        if needle not in html:
            errors.append(f"{rel}: missing {needle}")
    for forbidden in ("checkout.stripe.com", "buy.stripe.com", "data-customer-id=", "api_key=", "testimonio de cliente"):
        if forbidden in html:
            errors.append(f"{rel}: unexpected live feature: {forbidden}")
free = (ROOT / "docs" / "insertar-calculadora" / "index.html")
if not free.is_file() or 'href="/partners/"' not in free.read_text(encoding="utf-8"):
    errors.append("Free embed page must link to commercial pilot")
for error in errors:
    print("ERROR:", error)
print("Partners smoke checks:", "OK" if not errors else f"{len(errors)} errors")
sys.exit(bool(errors))
